      rw_cells rsegs m rd [C8 (wz b)] -> bv_unsigned sp <= rd -> (rd + 8 <= b \/ b + 64 <= rd) -> rd + 8 <= B ->
      rw_cells rsegs m cbp [C8 (wz src); C8 (wz n)] -> bv_unsigned sp <= cbp -> (cbp + 16 <= b \/ b + 64 <= cbp) -> cbp + 16 <= B ->
      rw_cells rsegs m E [CB 24 ej] -> bv_unsigned sp <= E -> (E + 24 <= b \/ b + 64 <= E) -> E + 24 <= B ->
      (rd + 8 <= E \/ E + 24 <= rd) -> (cbp + 16 <= E \/ E + 24 <= cbp) ->
      bytes_at rsegs m src bs -> zlength bs = n -> rclient_range LB (bv_unsigned sp) src n ->
      (forall x' s', In (x', s') es -> src + n <= x' \/ x' + 24 + s' <= src) -> (src + n <= b \/ b + 64 <= src) ->
      (src + n <= E \/ E + 24 <= src) ->
      bv_unsigned sp <= b -> b + 64 <= B ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      (mb_need es insz n = true -> lb_bytes LB + mb_block_size (mb_grow es insz n) <= hs_LIVE_MAX H) ->
      (mb_need es insz n = true -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H) ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B -> B <= 2^64 ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - PUT_STACK -> bv_unsigned sp mod 16 = 0 ->
      bv_unsigned ra mod 2 = 0 ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      hs_SR H (put_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB b es insz n src E lo B bs m mo)
