  (* [comment removed for export] *)
  Definition putB_W (lo : Z) (sp : word) (E b : Z) (es : list mbe) (insz n x : Z) : list (Z * Z) :=
    [(lo, bv_unsigned sp); (E, E + 24);
     (fst (mb_b1 b es insz n x), fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x));
     (fst (mb_b2 b es insz n x), fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x));
     (b + 24, b + 64)]%Z.

  Definition putB_post (sp : word) (gp tp : word) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra : word) (F : bvmap 5 word) (fc : bv 32)
      (b : Z) (es : list mbe) (insz n x src E lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz n) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ munch (putB_W lo sp E b es insz n x) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' E (ErrCodeCells EC_clear)
      /\ bytes_at rsegs m' src bs
      /\ MBuf m' b (mb_put_es es insz n x) (insz + n).
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

  Lemma putB : forall (rd cbp b : Z) (es : list mbe) (insz n x src E lo : Z) (bs jd8 jR7 jR40 j8p j16a j16b ej : list byte)
      (ra sp : word) gp tp (t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
      (F : bvmap 5 word) fc (m : mem),
    MBmid m b es insz n x -> mb_ok es insz -> 1 <= n -> insz + n <= 2^30 ->
